# Generated by `bin/rails generate authentication`, with Roomies messages
class SessionsController < ApplicationController
  allow_unauthenticated_access only: %i[ new create ]
  # No record to authorize: signing in, signing up and the landing page are open to everyone
  skip_after_action :verify_authorized
  rate_limit to: 10, within: 3.minutes, only: :create, with: -> { redirect_to new_session_path, alert: "Try again later." }

  def new
    # "Log in to apply" sends the visitor back to the listing afterwards.
    # url_from only accepts addresses of this same site.
    if (return_to = url_from(params[:return_to]))
      session[:return_to_after_authenticating] = return_to
    end
  end

  def create
    if user = User.authenticate_by(params.permit(:email_address, :password))
      start_new_session_for user
      redirect_to after_authentication_url, notice: "Welcome back, #{user.full_name}!"
    else
      redirect_to new_session_path(email_address: params[:email_address]), alert: "Try another email address or password."
    end
  end

  def destroy
    terminate_session
    redirect_to root_path, notice: "You signed out. See you soon!", status: :see_other
  end
end
